ext('c12_phy_ch3',[
C("⚡","धारा के सूत्र और मात्रक",["I = q / t","मात्रक: एम्पियर (A)","1 A = 1 C/s","अदिश राशि"],"विद्युत धारा आवेश के प्रवाह की दर है। सूत्र है आई बराबर क्यू भाग टी, यानी प्रति सेकंड बहने वाला आवेश। इसका मात्रक एम्पियर है और एक एम्पियर का मतलब है एक कूलॉम प्रति सेकंड। धारा की दिशा परंपरा से धनात्मक आवेश की गति की दिशा मानी जाती है, जबकि धातु में असल में इलेक्ट्रॉन विपरीत दिशा में चलते हैं। धारा की दिशा होती है, पर वह सदिश के जोड़-नियमों का पालन नहीं करती, इसलिए यह अदिश राशि है।"),
Q("किसी तार में 5 सेकंड में 10 कूलॉम आवेश बहता है। धारा कितनी है?","I = q/t = 10/5 = 2 A","सूत्र लगाइए... धारा बराबर आवेश भाग समय। दस कूलॉम भाग पाँच सेकंड बराबर दो एम्पियर। यानी हर सेकंड दो कूलॉम आवेश तार के किसी भी अनुप्रस्थ काट से गुज़रता है।"),
C("🏃","अपवाह वेग और गतिशीलता",["v_d = eEτ/m","I = n·e·A·v_d","गतिशीलता μ = v_d/E","मात्रक: m²/Vs"],"तार में इलेक्ट्रॉन तेज़ गति से बेतरतीब घूमते हैं, पर विद्युत क्षेत्र लगाने पर उनमें एक औसत धीमी गति भी आ जाती है, जिसे अपवाह वेग कहते हैं। इसका सूत्र है ई गुणा क्षेत्र गुणा टाउ भाग एम। धारा का दूसरा रूप है आई बराबर एन ई ए गुणा अपवाह वेग, जहाँ एन इलेक्ट्रॉन घनत्व है। गतिशीलता यानी मोबिलिटी, अपवाह वेग को क्षेत्र से भाग देकर मिलती है। अपवाह वेग बहुत कम, लगभग मिलीमीटर प्रति सेकंड, होता है।"),
Q("अपवाह वेग इतना कम होने पर भी बल्ब तुरंत क्यों जलता है?","क्योंकि विद्युत क्षेत्र प्रकाश की गति के पास फैलता है और सभी इलेक्ट्रॉन एक साथ चलने लगते हैं","सोचिए... तार में पहले से हर जगह इलेक्ट्रॉन मौजूद हैं। स्विच दबाते ही विद्युत क्षेत्र पूरे तार में लगभग प्रकाश की गति से बन जाता है और सारे इलेक्ट्रॉन एक साथ चलने लगते हैं। इसलिए बल्ब तुरंत जलता है, भले अपवाह वेग धीमा हो।"),
C("🔌","प्रतिरोध और प्रतिरोधकता",["R = ρ l / A","ρ पदार्थ का गुण","चालकता σ = 1/ρ","मात्रक: Ω·m"],"किसी तार का प्रतिरोध उसकी लंबाई के समानुपाती और अनुप्रस्थ काट क्षेत्रफल के व्युत्क्रमानुपाती होता है। सूत्र है आर बराबर रो गुणा एल भाग ए। रो यानी प्रतिरोधकता पदार्थ का गुण है, तार की माप का नहीं। इसका मात्रक ओम मीटर है। चालकता प्रतिरोधकता का व्युत्क्रम होती है। तांबा और चाँदी की प्रतिरोधकता बहुत कम है, इसलिए तार इनके बनते हैं। नाइक्रोम की प्रतिरोधकता अधिक है, इसलिए हीटर में काम आता है।"),
Q("एक तार को खींचकर उसकी लंबाई दुगुनी कर दी जाए तो प्रतिरोध कितना हो जाएगा?","आयतन समान रहने पर R ∝ l²। लंबाई दुगुनी ⇒ R चार गुना","ध्यान से सोचिए... तार खींचने पर आयतन स्थिर रहता है। लंबाई दुगुनी हुई तो क्षेत्रफल आधा हो गया। प्रतिरोध एल भाग ए के समानुपाती है, तो दुगुना भाग आधा, यानी चार गुना। यह परीक्षा का पक्का प्रश्न है।"),
C("🌡️","ताप के साथ प्रतिरोध",["धातु: ताप बढ़े, R बढ़े","अर्धचालक: ताप बढ़े, R घटे","R = R₀(1 + αΔT)","α तापीय गुणांक"],"धातुओं में तापमान बढ़ने पर परमाणुओं का कंपन बढ़ जाता है, इलेक्ट्रॉन ज़्यादा टकराते हैं और प्रतिरोध बढ़ता है। इसका सूत्र है आर बराबर आर शून्य गुणा एक जमा अल्फ़ा डेल्टा टी। अर्धचालकों में ताप बढ़ने पर अधिक आवेश वाहक मुक्त होते हैं, इसलिए प्रतिरोध घटता है। मिश्रातुओं जैसे मैंगनिन का प्रतिरोध ताप से लगभग नहीं बदलता, इसलिए मानक प्रतिरोध इनसे बनाते हैं।"),
Q("धातु और अर्धचालक के प्रतिरोध पर ताप का प्रभाव कैसे अलग है?","धातु: ताप बढ़ने पर प्रतिरोध बढ़ता है; अर्धचालक: ताप बढ़ने पर प्रतिरोध घटता है","अंतर याद कीजिए... धातुओं में टकराव बढ़ने से प्रतिरोध बढ़ता है, जबकि अर्धचालकों में अधिक आवेश वाहक बनने से प्रतिरोध घटता है। इस उलटे व्यवहार को याद रखिए।"),
C("🔗","श्रेणी और समांतर संयोजन",["श्रेणी: R = R₁ + R₂ + ...","समांतर: 1/R = 1/R₁ + 1/R₂","श्रेणी में धारा समान","समांतर में विभव समान"],"श्रेणी संयोजन में प्रतिरोध सीधे जुड़ते हैं, और हर प्रतिरोध से एक ही धारा गुज़रती है। समांतर संयोजन में हर प्रतिरोध पर विभवांतर समान रहता है और कुल धारा बँट जाती है। समतुल्य प्रतिरोध का व्युत्क्रम अलग-अलग प्रतिरोधों के व्युत्क्रमों का योग होता है। दो प्रतिरोधों के लिए सीधा सूत्र है गुणनफल भाग योग। घरों में उपकरण समांतर में जुड़ते हैं ताकि सबको पूरा विभव मिले।"),
Q("2 Ω और 3 Ω के प्रतिरोध समांतर में जुड़े हैं। समतुल्य प्रतिरोध ज्ञात कीजिए।","R = (2×3)/(2+3) = 6/5 = 1.2 Ω","दो प्रतिरोधों के लिए गुणनफल भाग योग का सूत्र लगाइए। दो गुणा तीन बराबर छह और दो जमा तीन बराबर पाँच। इसलिए छह बटा पाँच यानी एक दशमलव दो ओम। ध्यान दीजिए, समांतर संयोजन में परिणाम सबसे छोटे प्रतिरोध से भी छोटा आता है।"),
C("🔋","सेल, आंतरिक प्रतिरोध और टर्मिनल विभव",["ε = V + Ir","V = ε − Ir","I = ε/(R + r)","विसर्जन में V < ε"],"हर सेल का अपना एक आंतरिक प्रतिरोध होता है। जब सेल से धारा निकलती है, तो उसके टर्मिनलों के बीच विभवांतर विद्युत वाहक बल से कम हो जाता है। सूत्र है वी बराबर ई ऋण आई गुणा आर। सर्किट में धारा ई भाग आर जमा छोटे आर होती है। जब बाहर कोई भार जुड़ा न हो, यानी खुला परिपथ, तो टर्मिनल विभव ई एम एफ के बराबर होता है।"),
Q("12 V के सेल का आंतरिक प्रतिरोध 1 Ω है। 5 Ω से जोड़ने पर धारा और टर्मिनल विभव निकालिए।","I = 12/(5+1) = 2 A, V = 12 − 2×1 = 10 V","चरणबद्ध हल कीजिए... कुल प्रतिरोध पाँच जमा एक बराबर छह ओम। धारा बारह भाग छह बराबर दो एम्पियर। टर्मिनल विभव बारह ऋण दो गुणा एक बराबर दस वोल्ट। यही दस वोल्ट बाहरी प्रतिरोध पर मिलता है, जो दो गुणा पाँच से भी जाँचा जा सकता है।"),
C("🌐","किरचॉफ़ के नियम का उपयोग",["जंक्शन नियम: ΣI = 0","लूप नियम: ΣV = 0","आवेश संरक्षण","ऊर्जा संरक्षण"],"किरचॉफ़ के दो नियम जटिल परिपथ हल करने के काम आते हैं। पहला, जंक्शन नियम, कहता है कि किसी बिंदु पर आने वाली धाराओं का योग जाने वाली धाराओं के योग के बराबर होता है। यह आवेश संरक्षण पर आधारित है। दूसरा, लूप नियम, कहता है कि किसी बंद लूप में विभव परिवर्तनों का बीजगणितीय योग शून्य होता है। यह ऊर्जा संरक्षण पर आधारित है। हल करते समय धारा की दिशा मानकर चिह्न का ध्यान रखिए।"),
Q("किरचॉफ़ का लूप नियम किस संरक्षण नियम पर आधारित है?","ऊर्जा संरक्षण","याद कीजिए... बंद लूप में एक चक्कर लगाने पर कुल ऊर्जा परिवर्तन शून्य होता है, क्योंकि ऊर्जा न बनती है और न नष्ट होती है। इसलिए लूप नियम ऊर्जा संरक्षण पर आधारित है और जंक्शन नियम आवेश संरक्षण पर।"),
C("⚖️","व्हीटस्टोन सेतु और मीटर सेतु",["संतुलन: P/Q = R/S","गैल्वेनोमीटर में शून्य विक्षेप","अज्ञात प्रतिरोध नापना","मीटर सेतु: S = R(100 − l)/l"],"व्हीटस्टोन सेतु में चार प्रतिरोध एक चतुर्भुज में जुड़े होते हैं और कर्णों पर सेल और गैल्वेनोमीटर लगे होते हैं। संतुलन की स्थिति में गैल्वेनोमीटर में धारा शून्य होती है और पी भाग क्यू बराबर आर भाग एस होता है। इससे अज्ञात प्रतिरोध नापा जा सकता है। मीटर सेतु में एक मीटर लंबे तार पर संतुलन बिंदु ढूँढकर अज्ञात प्रतिरोध निकाला जाता है। इसमें लंबाई का अनुपात प्रतिरोध के अनुपात के बराबर होता है।"),
Q("सेतु संतुलित है, P = 10 Ω, Q = 20 Ω, R = 15 Ω। S ज्ञात कीजिए।","P/Q = R/S ⇒ S = RQ/P = 15×20/10 = 30 Ω","संतुलन शर्त लगाइए। दस भाग बीस बराबर पंद्रह भाग एस। क्रॉस गुणा करने पर एस बराबर पंद्रह गुणा बीस भाग दस, यानी तीन सौ भाग दस, यानी तीस ओम। गैल्वेनोमीटर में शून्य धारा होने पर यही शर्त सही है।"),
C("💡","विद्युत शक्ति और ऊर्जा",["P = VI = I²R = V²/R","ऊर्जा = P × t","1 kWh = 3.6 × 10⁶ J","बिजली का बिल"],"विद्युत शक्ति ऊर्जा के उपयोग की दर है। सूत्र हैं वी आई, आई वर्ग आर और वी वर्ग भाग आर। मात्रक वाट है। ऊर्जा बराबर शक्ति गुणा समय। बिजली के बिल में इकाई किलोवाट घंटा होती है, जिसे यूनिट कहते हैं। एक किलोवाट घंटा बराबर तीन दशमलव छह गुणा दस की छह घात जूल। हीटर और बल्ब जैसे उपकरणों की शक्ति पर उनकी खपत निर्भर करती है। बचत के लिए कम वाट वाले एल ई डी बल्ब बेहतर हैं।"),
Q("100 W का बल्ब 5 घंटे जलता है। कितनी यूनिट बिजली खर्च होगी?","ऊर्जा = 100 W × 5 h = 500 Wh = 0.5 kWh = 0.5 यूनिट","शक्ति को किलोवाट में बदलिए। सौ वाट बराबर शून्य दशमलव एक किलोवाट। पाँच घंटे से गुणा करने पर शून्य दशमलव पाँच किलोवाट घंटा। यानी आधी यूनिट। बिल निकालने में यही तरीक़ा काम आता है।"),
C("✍️","उत्तर लिखने की रणनीति",["सूत्र पहले लिखें","इकाई ज़रूर लिखें","परिपथ चित्र बनाएँ","चरण-दर-चरण हल"],"इस अध्याय में सूत्र बहुत हैं, इसलिए उन्हें समूहों में याद कीजिए: धारा, प्रतिरोध, संयोजन, सेल और किरचॉफ़। संख्यात्मक प्रश्न में पहले दिए हुए और माँगे हुए को लिखिए, फिर सूत्र, फिर मान रखकर हल और अंत में इकाई सहित उत्तर। परिपथ का साफ़ चित्र बनाइए और धारा की दिशा तीर से दिखाइए। इससे आंशिक अंक भी मिलते हैं और ग़लती कम होती है।"),
],7)
